import Foundation

/// What each code's witnesses meant.
extension StyleRecovery {
    /// What every code's witnesses meant, bucketed per rule. Codes that are
    /// settled without evidence - generated by the build, or already a default code -
    /// go straight into the report.
    static func readCodes(
        _ evidence: Evidence,
        into report: inout Report,
        rules: DefaultRuleBook
    ) -> [CodeReading] {
        // In key order: what follows breaks ties by who came first, and a dictionary
        // hands its keys over differently in every process.
        let codes = evidence.codes.sorted(by: { $0.key < $1.key })
        // Each code is read on its own, over every core; 1 code may hold 1000000
        // witnesses and another 10, so they are handed out 1 at a time.
        let results = UnsafeMutableBufferPointer<(outcome: Outcome?, reading: CodeReading?)>.allocate(
            capacity: codes.count
        )
        results.initialize(repeating: (nil, nil))
        defer {
            results.deinitialize()
            results.deallocate()
        }
        // Each iteration writes only its own slot: nothing is shared.
        nonisolated(unsafe) let slots = results
        DispatchQueue.concurrentPerform(iterations: codes.count) { at in
            slots[at] = reading(codes[at].key, codes[at].value, rules: rules)
        }
        var read: [CodeReading] = []
        for (at, (key, _)) in codes.enumerated() {
            if let outcome = results[at].outcome { report.outcomes[key] = outcome }
            if let reading = results[at].reading { read.append(reading) }
        }
        return read
    }

    /// 1 code read: its outcome where already settled, and what its witnesses meant.
    private static func reading(
        _ key: String,
        _ code: Evidence.ForCode,
        rules: DefaultRuleBook
    ) -> (outcome: Outcome?, reading: CodeReading?) {
        var outcome = Outcome(
            kind: code.kind,
            type: code.type,
            witnesses: code.sources.count,
            elements: code.elements,
            unmatched: code.unmatched,
            ambiguous: code.ambiguous,
            meaning: "",
            status: .noEvidence,
            resolutions: code.resolutions
        )

        // A code the default set already uses is not foreign: nothing to write.
        if Self.generated.contains(Evidence.key(code.kind, code.type).uppercased()) {
            outcome.status = .resolved
            outcome.meaning = "generated by the build, no ground source"
            return (outcome, nil)
        }
        let foreign = !rules.alreadyEmits(code.type, kind: code.kind)
        if !foreign {
            outcome.status = .resolved
            outcome.meaning = "already a default code"
        }
        // A default code's outcome is settled whatever its witnesses; a foreign code's
        // only where it has none.
        guard !code.sources.isEmpty else { return (outcome, nil) }

        var buckets: [String: MeaningBucket] = [:]
        var meant = 0
        for (id, tags) in code.sources {
            // An area matching coastline ways witnesses nothing: a land ring is cut from
            // them, and so are the beaches, bays and reserves along the shore. Taken for
            // either, the land layer would be silenced or repainted as sand.
            guard let tag = DefaultRuleBook.meaning(of: tags),
                code.kind != .area || tag != DefaultRuleBook.coastline
            else { continue }
            meant += 1
            // Keyed by the rule the meaning opens, so 2 spellings of one rule are one
            // meaning, not by the code it emits: one code may draw several things. The first
            // rule whose condition the source meets: a small town is no witness for the big
            // towns' line.
            let opened = rules.lines(for: tag, kind: code.kind).map { all in
                all.first { $0.holds(for: tags) != false } ?? all[0]
            }
            let bucket =
                opened.map { "\(code.kind.rawValue)@\($0.text)" }
                ?? "\(code.kind.rawValue)=\(tag)"
            buckets[bucket, default: MeaningBucket(lines: [])].tags[tag, default: 0] += 1
            buckets[bucket]?.ids.insert(id)
            // Areas only: a point planted for a building carries its tags too.
            if code.kind == .area, let built = tags[DefaultRuleBook.buildingKey],
                built != DefaultRuleBook.noBuilding
            {
                buckets[bucket]?.built += 1
            }
            if let zoom = code.sourceZoom[id] {
                buckets[bucket]?.resolutions[Int(zoom), default: 0] += 1
            }
        }
        // Tags sharing a first rule may differ after it: the bucket stands for the
        // rules of its commonest tag, whichever witness came first.
        // From the line the bucket opened on: the stricter ones above it were not met.
        for (bucket, meaning) in buckets {
            let all = rules.lines(for: meaning.name, kind: code.kind) ?? []
            let from = all.firstIndex { "\(code.kind.rawValue)@\($0.text)" == bucket } ?? 0
            buckets[bucket]?.lines = Array(all[from...])
        }
        return (
            foreign ? nil : outcome,
            CodeReading(
                key: key,
                code: code,
                buckets: buckets,
                meant: meant,
                foreign: foreign
            )
        )
    }

    /// A bucket's rules widened by those of its other tags this code draws most of:
    /// a stray few of a tag that another code draws do not take that tag's rule along.
    static func widened(_ entry: CodeReading, rules: DefaultRuleBook, tagLeader: [String: Int]) -> CodeReading {
        var buckets = entry.buckets
        for (bucket, meaning) in entry.buckets {
            let kind = entry.code.kind
            let led = meaning.tags.filter { tag, count in
                tag != meaning.name && count >= fewestWitnesses
                    && count >= tagLeader["\(kind.rawValue)@\(tag)"] ?? count
            }
            guard !led.isEmpty else { continue }
            var seen = Set(meaning.lines.map { $0.file + ":" + $0.text })
            for tag in led.keys.sorted() {
                for line in rules.lines(for: tag, kind: kind) ?? []
                where seen.insert(line.file + ":" + line.text).inserted {
                    buckets[bucket]?.lines.append(line)
                }
            }
        }
        return CodeReading(
            key: entry.key,
            code: entry.code,
            buckets: buckets,
            meant: entry.meant,
            foreign: entry.foreign
        )
    }
}
